import {generateAsset,assetToSvg} from './art-kit.js';
import {returnRewards} from './rewards.js';
const fmt=n=>new Intl.NumberFormat('pt-BR').format(Math.max(0,Math.floor(n)));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class ReturnScreen{
 constructor({music,soft,onSave,onFinish}){this.music=music;this.soft=soft;this.onSave=onSave;this.onFinish=onFinish;this.active=false;this.settling=false;this.token=0;this.dialog=document.getElementById('returnDialog');this.dialog.addEventListener('cancel',e=>e.preventDefault());}
 balances(s){return this.active?this.display:{bank:s.bank,essence:s.essence,materials:s.materials};}
 show(s){if(this.active)return;this.state=s;this.result=s.lastResult;if(!this.result)return;this.active=true;this.page=0;this.cards=Array.isArray(this.result.resources)?this.result.resources:returnRewards(null,this.result.bag,this.result.kept);this.display={bank:s.bank-this.result.kept,essence:s.essence-(this.result.earnedEssence||0),materials:s.materials.map((n,i)=>n-(this.result.keptMaterials?.[i]||0))};this.music.silence();this.render();this.dialog.showModal();this.music.reward();document.getElementById('rewardOK').focus();}
 render(){const r=this.result,death=r.reason==='death',page=this.cards.slice(this.page*4,this.page*4+4),more=(this.page+1)*4<this.cards.length;
  this.dialog.innerHTML=`<div class="return-heading"><span class="eyebrow">REFÚGIO · ${r.mode==='abyss'?'ABISMO · '+fmt(r.depth)+' M':'ANDAR '+r.floor}</span><h2>${death?(r.depleted==='rhythm'?'SEM FÔLEGO':r.depleted==='health'?'VIDA ESGOTADA':'FIM DA DESCIDA'):r.reason==='victory'?'VITÓRIA!':'SAQUE DA DESCIDA'}</h2><p>${r.lost?`◇ ${fmt(r.kept)} SALVAS · ${fmt(r.lost)} PERDIDAS`:'SAQUE SALVO'}</p>${r.zagPasses?'<p class="zag-return">+'+fmt(r.zagPasses)+' PASSES</p>':''}${r.secured?'<p class="secured-summary">↑ JÁ NA BASE · '+fmt(r.secured.coins)+' MOEDAS · '+fmt(r.secured.materials.reduce((a,b)=>a+b,0))+' CRISTAIS</p>':''}</div><div class="reward-grid">${page.map((card,i)=>`<article class="reward-card" data-index="${i}"><span class="reward-art">${assetToSvg(generateAsset(card.art,{variant:card.kind,seed:71+i}))}</span><h3>${escape(card.name)}</h3><strong data-count="${Number(card.value)||0}">+0</strong><small>${card.destination==='essence'?'ESSÊNCIAS':card.destination.startsWith('material-')?'CRISTAIS':'MOEDAS'}</small></article>`).join('')}</div><div class="return-bottom"><span>SEQUÊNCIA ${r.peak}× · ${this.page+1}/${Math.ceil(this.cards.length/4)}<small>★ ${r.earnedStars||0} ESTRELAS GUARDADAS · ${fmt(r.score||0)} PONTOS</small></span><button class="primary" id="rewardOK">${more?'PRÓXIMOS →':'GUARDAR TUDO ✓'}</button></div>`;
  document.getElementById('rewardOK').onclick=()=>{if(more){this.page++;this.render();document.getElementById('rewardOK').focus();}else this.collect();};
  const token=++this.token,start=performance.now(),elements=[...this.dialog.querySelectorAll('.reward-card')],sounded=new Set();
  const frame=now=>{if(token!==this.token||this.settling)return;let complete=true;elements.forEach((el,i)=>{const age=now-start-i*160,p=this.soft()?1:Math.min(1,Math.max(0,age/600));if(age>=0&&!sounded.has(i)){sounded.add(i);this.music.loot(i);}el.classList.toggle('revealed',age>=0||this.soft());el.querySelector('[data-count]').textContent='+'+fmt(page[i].value*(1-(1-p)**3));if(p<1)complete=false;});if(!complete)requestAnimationFrame(frame);};requestAnimationFrame(frame);
 }
 collect(){if(this.settling)return;this.settling=true;this.token++;const startBalance={...this.display},rect=this.dialog.getBoundingClientRect(),origins=[...this.dialog.querySelectorAll('.reward-art')].map(el=>el.getBoundingClientRect());this.result.presented=true;this.onSave();this.dialog.close();this.music.reward();
  if(!this.soft())this.cards.filter(c=>c.value>0).forEach((card,i)=>{const destination=document.getElementById(card.destination).getBoundingClientRect(),origin=origins[i%origins.length]||rect,x=origin.left+origin.width/2,y=origin.top+origin.height/2;for(let j=0;j<3;j++){const token=document.createElement('div');token.className='flying-reward';token.innerHTML=assetToSvg(generateAsset('crystal',{variant:card.destination==='essence'?1:card.kind,seed:i}));token.style.left=x+'px';token.style.top=y+'px';document.body.append(token);const dx=destination.left+destination.width/2-x,dy=destination.top+destination.height/2-y;const a=token.animate([{transform:'translate(-50%,-50%) scale(1)',opacity:1},{transform:`translate(calc(-50% + ${dx*.35+(j-1)*34}px),calc(-50% + ${dy*.3-60}px)) scale(1.2)`,opacity:1,offset:.35},{transform:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px)) scale(.25)`,opacity:0}],{duration:780,delay:i*50+j*45,easing:'cubic-bezier(.4,0,.4,1)',fill:'both'});a.finished.then(()=>token.remove(),()=>token.remove());}});
  const started=performance.now(),duration=this.soft()?250:1100;const frame=now=>{const p=Math.min(1,(now-started)/duration);this.display={bank:startBalance.bank+this.result.kept*p,essence:startBalance.essence+(this.result.earnedEssence||0)*p,materials:startBalance.materials.map((n,i)=>n+(this.result.keptMaterials?.[i]||0)*p)};document.getElementById('bank').textContent=fmt(this.display.bank);document.getElementById('essence').textContent=fmt(this.display.essence);this.display.materials.forEach((n,i)=>{document.getElementById('material-'+i).textContent=fmt(n);});if(p<1)requestAnimationFrame(frame);else{this.active=false;this.settling=false;this.onFinish();}};requestAnimationFrame(frame);
 }
}
